{
  "name": "Customized Bicycle Manufacturing Process",
  "resources": [
    {
      "name": "Sales Department",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Storehouse",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "Engineering Department",
      "capacity": 1,
      "resource_type": "department"
    }
  ],
  "events": [
    {
      "id": "event_order_received",
      "name": "Order received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Order"
    },
    {
      "id": "event_order_rejected",
      "name": "Order rejected",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_order_accepted_sales",
      "name": "Order accepted and departments informed",
      "event_position": "intermediate",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_send_info_storehouse",
      "name": "Send order info to storehouse",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Order Info"
    },
    {
      "id": "event_send_info_engineering",
      "name": "Send order info to engineering",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Order Info"
    },
    {
      "id": "event_receive_info_storehouse",
      "name": "Receive order info",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Order Info"
    },
    {
      "id": "event_receive_info_engineering",
      "name": "Receive order info",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Order Info"
    },
    {
      "id": "event_storehouse_ready",
      "name": "Storehouse processing complete",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Parts Ready Notification"
    },
    {
      "id": "event_receive_parts_ready",
      "name": "Receive parts ready notification",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Parts Ready Notification"
    },
    {
      "id": "event_send_bike_to_sales",
      "name": "Send assembled bike to sales",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Assembled Bicycle"
    },
    {
      "id": "event_receive_bike_sales",
      "name": "Receive assembled bike",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Assembled Bicycle"
    },
    {
      "id": "event_order_completed",
      "name": "Order completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_evaluate_order",
      "name": "Evaluate order",
      "bpmn_type": "UserTask",
      "resource_name": "Sales Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_obj_order"],
      "output_data_ids": []
    },
    {
      "id": "task_process_part_list",
      "name": "Process part list of the order",
      "bpmn_type": "ManualTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_obj_part_list"],
      "output_data_ids": []
    },
    {
      "id": "task_check_part_availability",
      "name": "Check required quantity of part",
      "bpmn_type": "UserTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": true,
      "input_data_ids": ["data_obj_part_list"],
      "output_data_ids": []
    },
    {
      "id": "task_reserve_part",
      "name": "Reserve part in-house",
      "bpmn_type": "UserTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_backorder_part",
      "name": "Back-order part",
      "bpmn_type": "UserTask",
      "resource_name": "Storehouse",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_prepare_assembly",
      "name": "Prepare everything for bicycle assembly",
      "bpmn_type": "ManualTask",
      "resource_name": "Engineering Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_obj_order"],
      "output_data_ids": []
    },
    {
      "id": "task_assemble_bicycle",
      "name": "Assemble bicycle",
      "bpmn_type": "ManualTask",
      "resource_name": "Engineering Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_ship_bicycle",
      "name": "Ship bicycle to customer",
      "bpmn_type": "ManualTask",
      "resource_name": "Sales Department",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_order_decision",
      "name": "Order accepted?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_reject",
          "condition": "rejected"
        },
        {
          "flow_id": "flow_accept",
          "condition": "accepted"
        }
      ]
    },
    {
      "id": "gw_sales_split",
      "name": "Notify departments",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_sales_join",
      "name": "Wait for assembly completion",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_part_availability",
      "name": "Part available?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_available",
          "condition": "available"
        },
        {
          "flow_id": "flow_not_available",
          "condition": "not available"
        }
      ]
    },
    {
      "id": "gw_loop_join",
      "name": "Part processing merge",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_more_parts",
      "name": "More parts on list?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_next_part",
          "condition": "yes"
        },
        {
          "flow_id": "flow_all_parts_done",
          "condition": "no"
        }
      ]
    },
    {
      "id": "gw_engineering_join",
      "name": "Wait for parts and preparation",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "flow_1",
      "source_id": "event_order_received",
      "target_id": "task_evaluate_order",
      "condition_name": null
    },
    {
      "id": "flow_2",
      "source_id": "task_evaluate_order",
      "target_id": "gw_order_decision",
      "condition_name": null
    },
    {
      "id": "flow_reject",
      "source_id": "gw_order_decision",
      "target_id": "event_order_rejected",
      "condition_name": "rejected"
    },
    {
      "id": "flow_accept",
      "source_id": "gw_order_decision",
      "target_id": "gw_sales_split",
      "condition_name": "accepted"
    },
    {
      "id": "flow_to_info_storehouse",
      "source_id": "gw_sales_split",
      "target_id": "event_send_info_storehouse",
      "condition_name": null
    },
    {
      "id": "flow_to_info_engineering",
      "source_id": "gw_sales_split",
      "target_id": "event_send_info_engineering",
      "condition_name": null
    },
    {
      "id": "flow_sales_wait_bike",
      "source_id": "event_send_info_sales_wait",
      "target_id": "event_receive_bike_sales",
      "condition_name": null
    },
    {
      "id": "flow_storehouse_start",
      "source_id": "event_receive_info_storehouse",
      "target_id": "task_process_part_list",
      "condition_name": null
    },
    {
      "id": "flow_storehouse_check",
      "source_id": "task_process_part_list",
      "target_id": "task_check_part_availability",
      "condition_name": null
    },
    {
      "id": "flow_storehouse_decide",
      "source_id": "task_check_part_availability",
      "target_id": "gw_part_availability",
      "condition_name": null
    },
    {
      "id": "flow_available",
      "source_id": "gw_part_availability",
      "target_id": "task_reserve_part",
      "condition_name": "available"
    },
    {
      "id": "flow_not_available",
      "source_id": "gw_part_availability",
      "target_id": "task_backorder_part",
      "condition_name": "not available"
    },
    {
      "id": "flow_res_merge",
      "source_id": "task_reserve_part",
      "target_id": "gw_loop_join",
      "condition_name": null
    },
    {
      "id": "flow_back_merge",
      "source_id": "task_backorder_part",
      "target_id": "gw_loop_join",
      "condition_name": null
    },
    {
      "id": "flow_check_more",
      "source_id": "gw_loop_join",
      "target_id": "gw_more_parts",
      "condition_name": null
    },
    {
      "id": "flow_next_part",
      "source_id": "gw_more_parts",
      "target_id": "task_check_part_availability",
      "condition_name": "yes"
    },
    {
      "id": "flow_all_parts_done",
      "source_id": "gw_more_parts",
      "target_id": "event_storehouse_ready",
      "condition_name": "no"
    },
    {
      "id": "flow_engineering_start",
      "source_id": "event_receive_info_engineering",
      "target_id": "task_prepare_assembly",
      "condition_name": null
    },
    {
      "id": "flow_eng_prep_join",
      "source_id": "task_prepare_assembly",
      "target_id": "gw_engineering_join",
      "condition_name": null
    },
    {
      "id": "flow_eng_receive_parts",
      "source_id": "event_receive_parts_ready",
      "target_id": "gw_engineering_join",
      "condition_name": null
    },
    {
      "id": "flow_eng_assemble",
      "source_id": "gw_engineering_join",
      "target_id": "task_assemble_bicycle",
      "condition_name": null
    },
    {
      "id": "flow_eng_done",
      "source_id": "task_assemble_bicycle",
      "target_id": "event_send_bike_to_sales",
      "condition_name": null
    },
    {
      "id": "flow_sales_receive_bike",
      "source_id": "event_send_info_storehouse",
      "target_id": "event_receive_bike_sales",
      "condition_name": null
    },
    {
      "id": "flow_sales_ship",
      "source_id": "event_receive_bike_sales",
      "target_id": "task_ship_bicycle",
      "condition_name": null
    },
    {
      "id": "flow_sales_end",
      "source_id": "task_ship_bicycle",
      "target_id": "event_order_completed",
      "condition_name": null
    }
  ],
  "pools": [
    {
      "id": "pool_sales",
      "name": "Sales Department",
      "element_ids": [
        "event_order_received",
        "task_evaluate_order",
        "gw_order_decision",
        "event_order_rejected",
        "gw_sales_split",
        "event_send_info_storehouse",
        "event_send_info_engineering",
        "event_receive_bike_sales",
        "task_ship_bicycle",
        "event_order_completed"
      ]
    },
    {
      "id": "pool_storehouse",
      "name": "Storehouse",
      "element_ids": [
        "event_receive_info_storehouse",
        "task_process_part_list",
        "task_check_part_availability",
        "gw_part_availability",
        "task_reserve_part",
        "task_backorder_part",
        "gw_loop_join",
        "gw_more_parts",
        "event_storehouse_ready"
      ]
    },
    {
      "id": "pool_engineering",
      "name": "Engineering Department",
      "element_ids": [
        "event_receive_info_engineering",
        "task_prepare_assembly",
        "event_receive_parts_ready",
        "gw_engineering_join",
        "task_assemble_bicycle",
        "event_send_bike_to_sales"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_sales_to_storehouse",
      "source_id": "event_send_info_storehouse",
      "target_id": "event_receive_info_storehouse",
      "name": "Order Notification"
    },
    {
      "id": "mf_sales_to_engineering",
      "source_id": "event_send_info_engineering",
      "target_id": "event_receive_info_engineering",
      "name": "Order Notification"
    },
    {
      "id": "mf_storehouse_to_engineering",
      "source_id": "event_storehouse_ready",
      "target_id": "event_receive_parts_ready",
      "name": "Parts Reserved/Back-ordered"
    },
    {
      "id": "mf_engineering_to_sales",
      "source_id": "event_send_bike_to_sales",
      "target_id": "event_receive_bike_sales",
      "name": "Assembled Bicycle"
    }
  ],
  "data_objects": [
    {
      "id": "data_obj_order",
      "name": "Order for customized bike"
    },
    {
      "id": "data_obj_part_list",
      "name": "Part list"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
